type Manifest = Readonly<Record<string, string>>;

export async function addPrerenderRoute(
  store: ManifestStore,
  route: string,
  source: string,
): Promise<void> {
  const current: unknown = JSON.parse(await store.read());
  if (typeof current !== "object" || current === null || Array.isArray(current)) {
    throw new Error("invalid prerender manifest");
  }
  const manifest: Manifest = Object.fromEntries(Object.entries(current));
  await store.write(JSON.stringify({ ...manifest, [route]: source }));
}

